import { configureStore, createAction, createAsyncThunk, createReducer, Middleware, Reducer } from '@reduxjs/toolkit';
import { DateRange, Note, PaginationOption, SortOption } from '../types';
import { DatabaseService } from '../services/db';


export interface State {
  notes: Note[];
  username: string;
  password: string;

  // 状态相关
  isLoggedIn: boolean;
  isSyncing: boolean;
  syncMessage: string | null;
  editingNote: Note | null;
  addingNote: boolean;

  // TODO: remove
  syncDays: number;

  toasts: Toast[];

  paginationOption: PaginationOption;

  totalNotes: number;
}

export type Toast = { id: number; message: string ; color?: "default" | "green" | "yellow" | "red" }

export const Action = {
    login: createAction<void>('LOGIN'),
    logout: createAction<void>('LOGOUT'),
    setUsername: createAction<string>('SET_USERNAME'),
    setPassword: createAction<string>('SET_PASSWORD'),
    setNotes: createAction<{ notes: Note[], total: number }>('SET_NOTES'),
    setSyncing: createAction<boolean>('SET_SYNCING'),
    setDateRange: createAction<DateRange>('SET_DATE_RANGE'),
    setSortOption: createAction<SortOption>('SET_SORT_OPTION'),
    setEditingNote: createAction<Note | null>('SET_EDITING_NOTE'),
    setAddingNote: createAction<boolean>('SET_ADDING_NOTE'),
    setSyncDays: createAction<number>('SET_SYNC_DAYS'),
    addToast: createAction<Toast>('ADD_TOAST'),
    removeToast: createAction<number>('REMOVE_TOAST'),
    setPage: createAction<number>('SET_PAGE'),

    loadLocalNotes: createAsyncThunk("LOAD_LOCAL_NOTES",
        async ({ currentPage, pageSize, sortOption, dateRange }: PaginationOption) => {
            return await DatabaseService.getNotesPaginated(
                currentPage,
                pageSize,
                sortOption,
                dateRange
            );
        }),
};

export const initialState: State = {
  isLoggedIn: false,
  notes: [],
  username: '',
  password: '',
  isSyncing: false,
  syncMessage: null,
  paginationOption: { currentPage: 0, pageSize: 10, sortOption: { field: 'created_at', direction: 'desc' }, dateRange: { startDate: '', endDate: '' } },
  totalNotes: 1,
  editingNote: null,
  addingNote: false,
  syncDays: 7,
  toasts: [],
};

// 使用action creators在createReducer中定义addCase
export const noteReducer = createReducer(initialState, (builder) => {
  builder
    .addCase(Action.login, (state) => {
      state.isLoggedIn = true;
    })
    .addCase(Action.logout, (state) => {
      state.isLoggedIn = false;
      state.notes = [];
    })
    .addCase(Action.setUsername, (state, action) => {
      state.username = action.payload;
    })
    .addCase(Action.setPassword, (state, action) => {
      state.password = action.payload;
    })
    .addCase(Action.loadLocalNotes.fulfilled, (state, action) => {
      const { notes, total } = action.payload;
      state.notes = notes;
      state.totalNotes = total;
    })
    .addCase(Action.setSyncing, (state, action) => {
      state.isSyncing = action.payload;
    })
    .addCase(Action.setDateRange, (state, action) => {
      state.paginationOption.dateRange = action.payload;
    })
    .addCase(Action.setSortOption, (state, action) => {
      state.paginationOption.sortOption = action.payload;
    })
    .addCase(Action.setPage, (state, action) => {
      state.paginationOption.currentPage = action.payload;
    })
    .addCase(Action.setEditingNote, (state, action) => {
      state.editingNote = action.payload;
    })
    .addCase(Action.setAddingNote, (state, action) => {
      state.addingNote = action.payload;
    })
    .addCase(Action.addToast, (state, action) => {
      state.toasts.push(action.payload);
    })
    .addCase(Action.removeToast, (state, action) => {
      state.toasts = state.toasts.filter(toast => toast.id !== action.payload);
    });
});

const loggerMiddleware: Middleware = store => next => action => {
    console.log('Dispatching:', action);
    const result = next(action);
    console.log('Next State:', store.getState());
    return result;
  };

export const store = configureStore({
    reducer: noteReducer, 
    middleware: (getDefaultMiddleware) => getDefaultMiddleware().concat(loggerMiddleware)});

export type RootState = ReturnType<typeof store.getState>;
export type AppDispatch = typeof store.dispatch;
