import React from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { Action, State } from '../store';

const ToastBox: React.FC = () => {
  const state = useSelector((state: State) => state);
  const dispatch = useDispatch();

  const addToast = (message: string) => {
    const id = Date.now();
    dispatch(Action.addToast({ id, message }));

    // TODO: currently not working; make it work 
    setTimeout(() => {
      console.log("removing toast via ")
      removeToast(id);
    }, 10000);
  };

  const removeToast = (id: number) => {
    dispatch(Action.removeToast(id));
  };
  console.log("all toasts: ", state.toasts)

  return (
    <div className="toast-container">
      {state.toasts.map((toast) => (
        <div className={`toast ${toast.color || 'default'}`}>
          <span>{toast.message}</span>
          <button onClick={() => removeToast(toast.id)}>x</button>
        </div>
      ))}
    </div>
  );
};

export default ToastBox;
